CREATE DATABASE IF NOT EXISTS staysphere CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE staysphere;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS advertisements,wishlist,reviews,payments,bookings,hotel_amenities,amenities,rooms,hotel_images,hotels,cities,admins,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(20) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,date_of_birth DATE,address TEXT,profile_image VARCHAR(500),account_status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cities(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,state VARCHAR(120),description TEXT,image VARCHAR(500),status ENUM('active','inactive') DEFAULT 'active');
CREATE TABLE hotels(id INT AUTO_INCREMENT PRIMARY KEY,city_id INT NOT NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) UNIQUE,description TEXT,address VARCHAR(500),star_rating TINYINT DEFAULT 3,property_type VARCHAR(50) DEFAULT 'Hotel',cover_image VARCHAR(500),check_in_time TIME DEFAULT '14:00:00',check_out_time TIME DEFAULT '11:00:00',policies TEXT,status ENUM('active','inactive') DEFAULT 'active',featured BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE hotel_images(id INT AUTO_INCREMENT PRIMARY KEY,hotel_id INT NOT NULL,image_url VARCHAR(500) NOT NULL,FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE);
CREATE TABLE rooms(id INT AUTO_INCREMENT PRIMARY KEY,hotel_id INT NOT NULL,room_type VARCHAR(100) NOT NULL,bed_type VARCHAR(100),room_size VARCHAR(50),max_guests INT DEFAULT 2,total_rooms INT DEFAULT 1,price DECIMAL(10,2) NOT NULL,discount_percentage DECIMAL(5,2) DEFAULT 0,image_url VARCHAR(500),status ENUM('active','inactive') DEFAULT 'active',FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE);
CREATE TABLE amenities(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);
CREATE TABLE hotel_amenities(hotel_id INT,amenity_id INT,PRIMARY KEY(hotel_id,amenity_id),FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE,FOREIGN KEY(amenity_id) REFERENCES amenities(id));
CREATE TABLE bookings(id INT AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(40) UNIQUE NOT NULL,user_id INT NOT NULL,hotel_id INT NOT NULL,room_id INT NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL,rooms INT NOT NULL,guest_name VARCHAR(120),guest_email VARCHAR(150),guest_phone VARCHAR(20),guest_address TEXT,special_request TEXT,subtotal DECIMAL(10,2),tax DECIMAL(10,2),service_charge DECIMAL(10,2),total_amount DECIMAL(10,2),booking_status ENUM('pending','confirmed','completed','cancelled') DEFAULT 'pending',payment_status ENUM('pending','successful','failed','refunded') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(hotel_id) REFERENCES hotels(id),FOREIGN KEY(room_id) REFERENCES rooms(id),INDEX(room_id,check_in,check_out));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT UNIQUE NOT NULL,transaction_id VARCHAR(100) UNIQUE NOT NULL,amount DECIMAL(10,2),payment_method VARCHAR(50),payment_status ENUM('pending','successful','failed','refunded') DEFAULT 'pending',paid_at DATETIME,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,hotel_id INT NOT NULL,booking_id INT UNIQUE NOT NULL,rating TINYINT NOT NULL,comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(hotel_id) REFERENCES hotels(id),FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE wishlist(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,hotel_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,hotel_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE);
CREATE TABLE advertisements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),description TEXT,image VARCHAR(500),promotional_link VARCHAR(500),start_date DATE,end_date DATE,status ENUM('active','inactive') DEFAULT 'active');
